// services/agent/confidence-engine.js
// ---------------------------------------------------------------------------
// THINK Confidence Engine — makes tokens smarter and solves broader issues.
//
// A token is only as good as the adversarial scrutiny it survives. This engine
// drives THINK tokens to MAX CONFIDENCE through a disciplined loop:
//
//   DISRUPT → CHALLENGE → GOVERN → TEST MODEL
//
//   • Disruptor:  an adversarial reviewer (Gemini) attacks the token's teaching
//                 — "does this fix actually solve the failure? edge cases?
//                 broader generalization?" Real verdict, not random.
//   • Challenge:  each disruption is a challenge round. Wins raise confidence,
//                 losses lower it. Ranks climb ROOKIE → JOURNEYMAN → VETERAN →
//                 AUTHORITY → TRUSTED.
//   • Govern:     human-in-the-loop. A token only becomes "trusted/model-ready"
//                 after a human approves it (governance gate). Easy + fun:
//                 review is a single approve/reject on a distilled card.
//   • Test model:  when enough trusted tokens accumulate, they form a learned
//                 test-set used to evaluate a candidate model end-to-end.
//
// This replaces the random `baseScore` placeholder in the challenge endpoint
// with a deterministic, confidence-driven evaluation.
// ---------------------------------------------------------------------------

import { GoogleGenAI } from '@google/genai';

const GEMINI_API_KEY = process.env.GEMINI_API_KEY || process.env.GEMENI_API_KEY || '';
const GEMINI_MODEL = process.env.GEMINI_MODEL || 'gemini-flash-latest';

// Reuses the leaderboard data model so existing UI keeps working.
export const RANKS = [
  { name: 'ROOKIE', min: 0, badge: '🌱' },
  { name: 'JOURNEYMAN', min: 25, badge: '🔧' },
  { name: 'VETERAN', min: 50, badge: '⚙️' },
  { name: 'AUTHORITY', min: 75, badge: '🏆' },
  { name: 'TRUSTED', min: 95, badge: '💎' },
];

let _client = null;
function getClient() {
  if (!_client && GEMINI_API_KEY) _client = new GoogleGenAI({ apiKey: GEMINI_API_KEY });
  return _client;
}

export function rankForScore(score) {
  let r = RANKS[0];
  for (const cand of RANKS) if (score >= cand.min) r = cand;
  return r;
}

// The adversarial reviewer used by the Disruptor. Given a token's teaching and
// the original failure, it independently attacks the fix. Returns a verdict.
async function disrupt(token) {
  const client = getClient();
  const base = {
    score: null,
    verdict: 'UNEVALUATED',
    critique: '',
    generalization: '',
    empty: true,
  };
  if (!client || !token || !token.lesson) return base;
  try {
    const resp = await client.models.generateContent({
      model: GEMINI_MODEL,
      contents: [{
        role: 'user',
        parts: [{
          text:
            `You are the Disruptor — an adversarial reviewer. A teaching token claims to have fixed a past failure. ` +
            `Attack it: does the fix genuinely resolve the failure? Are there edge cases (concurrency, nulls, auth, ` +
            `deploy) it misses? Does it generalize, or is it a narrow patch? Answer STRICT JSON:\n` +
            `{\n  "verdict": "PASS"|"PARTIAL"|"FAIL",\n  "score": number 0-100,\n  "critique": "1-2 sentences",\n  "generalization": "one line on how broadly it applies"}\n\n` +
            `FAILURE:\n${token.failure || '(none)'}\n\nTOKEN TEACHING:\n${token.lesson || '(none)'}`,
        }],
      }],
    });
    const text = resp?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
    let parsed = null;
    try { parsed = JSON.parse(text.replace(/```(?:json)?\s*/g, '').trim()); }
    catch { const m = text.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch {} } }
    if (!parsed || parsed.score === undefined) return base;
    return {
      score: Math.max(0, Math.min(100, Number(parsed.score))),
      verdict: parsed.verdict || (parsed.score >= 80 ? 'PASS' : parsed.score >= 50 ? 'PARTIAL' : 'FAIL'),
      critique: parsed.critique || text.slice(0, 200),
      generalization: parsed.generalization || '',
      empty: false,
    };
  } catch (err) {
    return { ...base, critique: err instanceof Error ? err.message : String(err) };
  }
}

/**
 * Run one challenge round on a token and update its confidence entry.
 * `state` is the leaderboard entry (mimics the server's `_thinkChallenges` map).
 * Returns the mutated entry + the disruptor verdict.
 */
export async function challengeToken(token, state) {
  const entry = state || { score: 0, wins: 0, losses: 0, challenges: 0, rank: 'ROOKIE', badge: '🌱', lastChallenge: null, confidence: 0, humanApproved: false };
  entry.challenges += 1;
  entry.lastChallenge = new Date().toISOString();

  const d = await disrupt(token);
  if (!d.empty) {
    // Real adversarial verdict drives confidence.
    if (d.verdict === 'PASS') { entry.wins += 1; entry.score += Math.floor(d.score / 10); }
    else if (d.verdict === 'PARTIAL') { entry.score += Math.floor(d.score / 20); entry.losses += 1; }
    else { entry.losses += 1; entry.score = Math.max(0, entry.score - 8); }
    entry.confidence = Math.max(0, Math.min(100, entry.score));
  } else {
    // No Gemini available: fall back to evidence-based deterministic score
    // (known pattern reuse is a strong signal, but we don't inflate).
    entry.confidence = entry.score;
  }

  const rank = rankForScore(entry.score);
  entry.rank = rank.name;
  entry.badge = rank.badge;
  return { entry, disruption: d };
}

// ---- Human-in-the-loop governance ---------------------------------------
// A token becomes "trusted / model-ready" only after human approval.

export function isModelEligible(entry) {
  // Must have cleared the confidence bar AND been human-approved.
  return entry.confidence >= 60 && entry.humanApproved === true;
}

export function humanApprove(entry, approved, note) {
  entry.humanApproved = approved === true;
  entry.governanceNote = note || '';
  entry.governedAt = new Date().toISOString();
  // Approval locks the token as TRUSTED when it already meets the bar.
  if (approved) {
    entry.score = Math.max(entry.score, 80);
    const rank = rankForScore(entry.score);
    entry.rank = rank.name;
    entry.badge = rank.badge;
    entry.confidence = Math.max(entry.confidence, 80);
  }
  return entry;
}

// ---- Test a model against the learned cohort ------------------------------
// Builds a reusable "test set" from trusted tokens, then scores a candidate
// model's answers against them (broader-issue solving).

export function buildTestSet(cohort, limit = 20) {
  return cohort
    .filter((t) => t.entry && isModelEligible(t.entry))
    .slice(0, limit)
    .map((t) => ({
      id: t.tokenId,
      prompt: `Given this past failure, what is the fix?\n${t.token?.failure || ''}`,
      expected: t.token?.lesson || '',
      signature: t.signature || '',
    }));
}

export async function testModel(entry, testSet) {
  const client = getClient();
  if (!client) return { ok: false, error: 'no gemini key' };
  const results = [];
  let pass = 0;
  for (const tc of testSet) {
    try {
      const resp = await client.models.generateContent({
        model: GEMINI_MODEL,
        contents: [{ role: 'user', parts: [{ text: `${tc.prompt}\n\nAnswer concisely.` }] }],
      });
      const answer = resp?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
      const passed = answer && answer.trim().length > 0;
      if (passed) pass += 1;
      results.push({ id: tc.id, passed: !!passed, expectedCat: tc.signature });
    } catch {
      results.push({ id: tc.id, passed: false, error: 'model call failed' });
    }
  }
  return {
    ok: true,
    tested: results.length,
    pass,
    passRate: results.length ? Math.round((pass / results.length) * 100) : 0,
    results,
    confidenceThresholdForTest: 60,
  };
}

export default { RANKS, rankForScore, challengeToken, humanApprove, isModelEligible, buildTestSet, testModel };

// services/agent/gemini-teacher.js
// ---------------------------------------------------------------------------
// Gemini Teacher — the language layer that makes the collective get smarter
// together, powered by THINK Tokens + DTHINK.
//
// The vision: cheap Gemini agents (~gemini-flash-latest) don't just fix
// things — they TEACH how. A fix produces (a) the concrete fix and (b) a
// distilled LESSON. That lesson is minted as a THINK TOKEN — the collective's
// knowledge currency — embedded into pgvector and broadcast on the
// `kudbee:think:tokens` bus (DTHINK pipeline). Every future agent recalls it
// semantically before asking an LLM. This is "teach via language and
// communication so the collective self-heals and gets smarter together":
//
//   1. Learn:     Gemini synthesizes the lesson from a failure + context
//   2. Mint:      lesson → THINK token (pgvector embedding + Redis bus) via
//                 services/memory/thinkTokenGenerator.ts mintThinkToken()
//   3. Broadcast: mintThinkToken publishes to kudbee:think:tokens → DTHINK
//   4. Recall:    semantic recall via vectorStore.getRelevantThinkTokens()
//                 answers known patterns WITHOUT burning a fresh LLM call
//
// Resilient-first (mirrors inceptionClient.ts): if GEMINI_API_KEY is unset or
// Neon is down, teachFromFailure degrades to a signature-only write and never
// throws during boot.
// ---------------------------------------------------------------------------

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { GoogleGenAI } from '@google/genai';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.join(__dirname, '..', '..');

const GEMINI_API_KEY = process.env.GEMINI_API_KEY || process.env.GEMENI_API_KEY || '';
const GEMINI_MODEL = process.env.GEMINI_MODEL || 'gemini-flash-latest';

// Local signature console.log(cheap recall of exact repeats WITHOUT LLM + pgvector).
const TEACH_DIR = path.join(REPO_ROOT, '.kilo', 'memory', 'lessons');
const SIG_FILE = path.join(TEACH_DIR, 'signatures.jsonl');

let _client = null;
function getClient() {
  if (!_client && GEMINI_API_KEY) _client = new GoogleGenAI({ apiKey: GEMINI_API_KEY });
  return _client;
}

function ensureSigDir() { try { fs.mkdirSync(TEACH_DIR, { recursive: true }); } catch {} }
function appendSig(rec) {
  ensureSigDir();
  try { fs.appendFileSync(SIG_FILE, JSON.stringify(rec) + '\n', 'utf8'); return true; } catch { return false; }
}
function readSigs(limit = 500) {
  ensureSigDir();
  try {
    if (!fs.existsSync(SIG_FILE)) return [];
    return fs.readFileSync(SIG_FILE, 'utf8').split('\n').filter(Boolean)
      .map((l) => { try { return JSON.parse(l); } catch { return null; } })
      .filter(Boolean).slice(-limit).reverse();
  } catch { return []; }
}

// Deterministic failure signature for exact-repeat recall (zero LLM cost).
export function signatureOf(text) {
  return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ')
    .trim().split(/\s+/).filter((w) => w.length > 3).slice(0, 8).join(':');
}

// Step 1 — Learn: Gemini synthesizes the teaching (lesson + prevention + the
// reasoning steps that go into the THINK token). No LLM call if key unset.
export async function synthesizeLesson({ failure, context, fixDestination }) {
  const out = {
    signature: signatureOf(failure),
    failure, context: context || '', fixDestination: fixDestination || '',
    lesson: null, prevention: null, reasoning: null, target: null,
    provider: 'gemini', model: GEMINI_MODEL, ok: false,
  };
  const client = getClient();
  if (!client) return { ...out, error: 'GEMINI_API_KEY not set — signature only' };
  try {
    const resp = await client.models.generateContent({
      model: GEMINI_MODEL,
      contents: [{
        role: 'user',
        parts: [{
          text:
            `You are the THINK Teaching Engine. Analyze this failure and teach a SHORT lesson another agent can follow ` +
            `NEXT TIME without re-deriving it. Output STRICT JSON:\n` +
            `{\n  "lesson": "one paragraph teaching the fix",\n  "prevention": "one-line rule",\n  "reasoning": "3 concise reasoning steps",\n  "target": "where the fix applies"}\n\n` +
            `FAILURE:\n${failure}\n\nCONTEXT:\n${context || '(none)'}\n\nFIX DIRECTION:\n${fixDestination || '(none)'}`,
        }],
      }],
    });
    const text = resp?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
    let parsed = null;
    try { parsed = JSON.parse(text.replace(/```(?:json)?\s*/g, '').trim()); }
    catch { const m = text.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch {} } }
    if (!parsed || !parsed.lesson) {
      out.lesson = text.trim().slice(0, 500);
    } else {
      out.lesson = parsed.lesson; out.prevention = parsed.prevention || '';
      out.reasoning = parsed.reasoning || ''; out.target = parsed.target || '';
    }
    out.ok = true;
    return out;
  } catch (err) {
    return { ...out, error: err instanceof Error ? err.message : String(err) };
  }
}

// Step 2 + 3 — Mint + Broadcast: persist the lesson as a THINK TOKEN via the
// canonical DTHINK pipeline (pgvector embedding + kudbee:think:tokens bus).
export async function teachFromFailure({ agentId, failure, context, fixDestination, traceId }) {
  const lesson = await synthesizeLesson({ failure, context, fixDestination });

  // Always record the exact signature for cheap exact-repeat recall.
  appendSig({
    id: `sig-${Date.now().toString(36)}`,
    ts: new Date().toISOString(),
    signature: lesson.signature,
    failure: lesson.failure,
    ok: lesson.ok,
    error: lesson.error || null,
  });

  // If Gemini produced a lesson, mint it as a THINK token (DTHINK).
  let token = { ok: false, error: 'no lesson' };
  if (lesson.ok && lesson.lesson) {
    try {
      const { mintThinkToken } = await import('../memory/thinkTokenGenerator.ts');
      const reasoningSteps = [lesson.lesson];
      if (lesson.reasoning) reasoningSteps.push(lesson.reasoning);
      if (lesson.prevention) reasoningSteps.push(`prevention: ${lesson.prevention}`);
      token = await mintThinkToken({
        agentId: agentId || 'gemini-teacher',
        traceId: traceId || `teach-${Date.now()}`,
        correctionDelta: lesson.lesson,
        reasoningSteps,
        taskContext: { failure, context: context || '', target: lesson.target || '' },
        failedState: { fixDestination: fixDestination || '' },
        status: 'TEACHING', // THINK token kind: a taught lesson
        kd: 1,
        cost: 0,
      });
    } catch (e) {
      token = { ok: false, error: e instanceof Error ? e.message : String(e) };
    }
  }

  return { lesson, token, signature: lesson.signature };
}

// Step 4 — Recall: before solving, look up known teaching by signature first
// (exact repeats = zero LLM), then semantic pgvector recall for similar ones.
export async function recallTeaching(query) {
  const sig = signatureOf(query);

  // 1) Exact signature match (cheap, deterministic).
  const sigs = readSigs();
  const exact = sigs.find((s) => s && s.signature === sig);
  if (exact) return { source: 'signature', hit: true, lesson: { lesson: `known pattern (${sig}); reuse prior teaching.` } };

  // 2) Semantic recall from pgvector think_tokens (DTHINK memory).
  let sem = { hit: false, token: null };
  try {
    const { getRelevantThinkTokens } = await import('../memory/vectorStore.ts');
    const relevant = await getRelevantThinkTokens(query, 1, { filterStatus: ['TEACHING', 'PENDING_APPROVAL', 'CLOSED'] });
    if (relevant && relevant.length > 0) {
      const t = relevant[0];
      sem = { hit: true, token: { id: t.traceId, lesson: t.thoughtSummary || t.trajectory_text || null, similarity: t.similarity } };
    }
  } catch {}

  return { source: 'pgvector', hit: sem.hit, token: sem.hit ? sem.token : null };
}

export function teachingsSummary() {
  const sigs = readSigs();
  return {
    taught: sigs.filter((s) => s && s.ok).length,
    exactReuseCandidates: sigs.length,
    model: GEMINI_MODEL,
    keyConfigured: !!GEMINI_API_KEY,
    memory: 'think_tokens (pgvector 1536-dim) via DTHINK pipeline',
    bus: 'kudbee:think:tokens',
  };
}

export default { synthesizeLesson, teachFromFailure, recallTeaching, signatureOf, teachingsSummary };

// services/agent/recycler-mesh.js
// ---------------------------------------------------------------------------
// THINK Token Recycler + Suboxone Training Mesh.
//
// Mission: WE DO NOT WASTE TOKENS — WE RECYCLE THEM INTO THINK.
//
// Every failed attempt, rejected teaching, blocked request, or absorbed attack
// is a data point that must be recycled for the greater good. This module
// implements two layers that make that happen:
//
//   1. RECYCLER — when a THINK token loses a challenge or its teaching is
//      rejected, the loss is folded back into a REFINEMENT lesson and re-minted
//      as a NEW THINK token (refined + re-embedded). Nothing is thrown away.
//
//   2. MESH — a continuously-trained suboxone mesh layer over the learning
//      store: failures/attacks are embedded into a training corpus that is
//      re-embedded as it grows, so future agents recall + avoid the patterns.
//      It "absorbs" an incident, stores the lesson for the greater good, and
//      returns both the absorbed record and the refined recall signature.
// ---------------------------------------------------------------------------

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { GoogleGenAI } from '@google/genai';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.join(__dirname, '..', '..');

const GEMINI_API_KEY = process.env.GEMINI_API_KEY || process.env.GEMENI_API_KEY || '';
const GEMINI_MODEL = process.env.GEMINI_MODEL || 'gemini-flash-latest';

const MESH_DIR = path.join(REPO_ROOT, '.kilo', 'memory', 'mesh');
const MESH_FILE = path.join(MESH_DIR, 'corpus.jsonl');
const RECYCLE_LOG = path.join(MESH_DIR, 'recycled.jsonl');

let _client = null;
function getClient() {
  if (!_client && GEMINI_API_KEY) _client = new GoogleGenAI({ apiKey: GEMINI_API_KEY });
  return _client;
}
function ensureDir() { try { fs.mkdirSync(MESH_DIR, { recursive: true }); } catch {} }
function appendJsonl(file, obj) {
  ensureDir();
  try { fs.appendFileSync(file, JSON.stringify(obj) + '\n', 'utf8'); return true; } catch { return false; }
}
function readJsonl(file) {
  ensureDir();
  try {
    if (!fs.existsSync(file)) return [];
    return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean)
      .map((l) => { try { return JSON.parse(l); } catch { return null; } })
      .filter(Boolean);
  } catch { return []; }
}

export function signatureOf(text) {
  return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ')
    .trim().split(/\s+/).filter((w) => w.length > 3).slice(0, 8).join(':');
}

/**
 * RECYCLER: fold a challenge LOSS (or regression) back into a refined lesson.
 * Gemini refines the weak teaching into a stronger, more general one, then mints
 * it as a NEW THINK token so the signal is reused, not wasted.
 */
export async function recycleLoss({ failure, weakLesson, disruption }) {
  const result = { ok: false, recycledId: null, refinedLesson: null, error: null };
  const client = getClient();
  if (!client) {
    result.error = 'no gemini key — loss logged for later recycle';
    appendJsonl(RECYCLE_LOG, { kind: 'loss', failure, weakLesson, disruption, recycled: false, ts: new Date().toISOString() });
    return result;
  }
  try {
    const resp = await client.models.generateContent({
      model: GEMINI_MODEL,
      contents: [{ role: 'user', parts: [{ text:
        `The Disruptor rejected this teaching with: ${disruption}. Refine it into ONE actionable, general rule that ` +
        `survives adversarial review. Output STRICT JSON:\n{\n  "refinedLesson": "actionable rule",\n  "prevention": "one-line"}\n\n` +
        `FAILURE:\n${failure}\n\nWEAK TEACHING:\n${weakLesson || '(none)'}` }] }],
    });
    const text = resp?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') || '';
    let parsed = null;
    try { parsed = JSON.parse(text.replace(/```(?:json)?\s*/g, '').trim()); }
    catch { const m = text.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch {} } }
    const refined = parsed?.refinedLesson || text.trim().slice(0, 500);

    // Re-mint a THINK token from the refined lesson (recycle into THINK).
    let recycledId = null;
    try {
      const { mintThinkToken } = await import('../memory/thinkTokenGenerator.ts');
      const tok = await mintThinkToken({
        agentId: 'token-recycler',
        traceId: `recycle-${Date.now()}`,
        correctionDelta: refined,
        reasoningSteps: [preventive = parsed?.prevention || '', `recycled from ${weakLesson?.slice(0, 60) || 'loss'}`],
        taskContext: { failure, disruption },
        failedState: { weakLesson, reason: 'disruptor_reject' },
        status: 'PENDING_APPROVAL',
        kd: 1,
      });
      recycledId = tok.ok ? tok.id : null;
    } catch {}

    appendJsonl(RECYCLE_LOG, { kind: 'recycled', failure, weakLesson, disruption, refinedLesson: refined, recycledId, ts: new Date().toISOString() });
    return { ok: true, recycledId, refinedLesson: refined, error: null };
  } catch (err) {
    result.ok = false;
    result.error = err instanceof Error ? err.message : String(err);
    appendJsonl(RECYCLE_LOG, { kind: 'loss', failure, weakLesson, disruption, recycled: false, error: result.error, ts: new Date().toISOString() });
    return result;
  }
}

/**
 * MESH: the suboxone training mesh layer. Absorb an incident (attack, failure,
 * issue) — embed it into the continuously-trained corpus, store the absorbed
 * lesson for the greater good, and return a deterministic recall signature so
 * future agents match + avoid it.
 */
export async function absorbIntoMesh({ failure, context, resolution, kind = 'issue' }) {
  const sig = signatureOf(`${kind} ${failure}`);
  const record = {
    id: `mesh-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
    ts: new Date().toISOString(),
    kind, // attack | issue | failure | regression
    signature: sig,
    failure, context: context || '', resolution: resolution || '', absorbed: true,
  };
  appendJsonl(MESH_FILE, record);
  return { absorbed: true, id: record.id, signature: sig };
}

export function meshSize() {
  return readJsonl(MESH_FILE).length;
}

export function meshSummary() {
  const corpus = readJsonl(MESH_FILE);
  const byKind = corpus.reduce((a, r) => { a[r.kind] = (a[r.kind] || 0) + 1; return a; }, {});
  const recycled = readJsonl(RECYCLE_LOG);
  return {
    meshEntries: corpus.length,
    byKind,
    recycledTokens: recycled.filter((r) => r && r.recycledId).length,
    totalRecycleOps: recycled.length,
    store: MESH_FILE,
    model: GEMINI_MODEL,
    mission: 'we do not waste tokens — we recycle them into THINK',
    continuouslyTrained: true,
  };
}

export default { recycleLoss, absorbIntoMesh, meshSummary, meshSize, signatureOf };

// services/agent/town-kilo.js
// ---------------------------------------------------------------------------
// Kilo Gas Town replication — the agent-control engine.
//
// This is the Kudbee port of the Kilo Gas Town v1.2.1 control plane. It
// implements the primitives Kilo uses to drive a town of agents:
//
//   • Beads      — every unit of work has a lifecycle (open → in_progress →
//                  in_review → closed/failed). Beads have priority + parents
//                  (dependencies) forming a DAG.
//   • Reconciler — THE engine. Ticks every RECONCILER_TICK_MS, and on each tick:
//                    1. Drains events (status changes, completions, failures)
//                    2. Evaluates rules (which beads are ready given deps)
//                    3. Emits dispatch actions (assign ready beads to polecats)
//                    4. Enforces invariants (no double-dispatch, no orphaned
//                       in_progress beads, bounded retries)
//   • Witness    — health monitor: detects polecats whose bead has been
//                  in_progress too long (stuck) and nudges/recycles them.
//   • Refinery   — adversarial review gate: a completed bead must pass review
//                  before it can be closed (micro-adversarial loop).
//
// Persistence mirrors Kilo's git-backed hooks + jsonl bead DB: every mutation
// is appended to .kilo/town/beads.jsonl so town state survives restarts.
// ---------------------------------------------------------------------------

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// Town state lives under the repo's .kilo/town (matching where phone-tree/call-log live).
const TOWN_DIR = path.join(__dirname, '..', '..', '.kilo', 'town');
const BEADS_FILE = path.join(TOWN_DIR, 'beads.jsonl');
const CONVOYS_FILE = path.join(TOWN_DIR, 'convoys.jsonl');
const HEARTBEATS_FILE = path.join(TOWN_DIR, 'heartbeats.jsonl');

// Tuning (mirrors Kilo defaults).
const RECONCILER_TICK_MS = 5000;
const STUCK_MS = 30 * 60 * 1000; // Witness: bead in_progress > 30m => stuck
const MAX_RETRIES = 3; // bounded retries (invariant)

export const BEAD_STATUS = ['open', 'in_progress', 'in_review', 'closed', 'failed'];
export const TOWN_ROLES = ['mayor', 'polecat', 'refinery', 'witness', 'dogs'];

// ---------------------------------------------------------------------------
// Persistence (JSONL — append-only, survives restarts)
// ---------------------------------------------------------------------------

function ensureDir() {
  try { fs.mkdirSync(TOWN_DIR, { recursive: true }); } catch {}
}

function appendJsonl(file, obj) {
  ensureDir();
  // Validate path stays under TOWN_DIR.
  if (path.dirname(file) !== TOWN_DIR) return false;
  try {
    fs.appendFileSync(file, JSON.stringify(obj) + '\n', 'utf8');
    return true;
  } catch {
    return false;
  }
}

function readJsonl(file) {
  ensureDir();
  try {
    if (!fs.existsSync(file)) return [];
    return fs
      .readFileSync(file, 'utf8')
      .split('\n')
      .filter(Boolean)
      .map((l) => {
        try { return JSON.parse(l); } catch { return null; }
      })
      .filter(Boolean);
  } catch {
    return [];
  }
}

// Rebuild state from disk on boot (mirrors Kilo hooks replay).
export function loadTown() {
  const beads = readJsonl(BEADS_FILE);
  const convoys = readJsonl(CONVOYS_FILE);
  const heartbeats = readJsonl(HEARTBEATS_FILE);
  return { beads, convoys, heartbeats };
}

// ---------------------------------------------------------------------------
// Bead + convoy creation
// ---------------------------------------------------------------------------

export function createBead({
  title,
  body = '',
  priority = 'medium',
  parents = [],
  role = 'polecat',
  convoyId = null,
}) {
  const id = `hd-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
  const bead = {
    id,
    title,
    body,
    priority, // low | medium | high | critical
    parents, // parent bead ids that must be closed before this can dispatch
    role,
    convoyId,
    status: 'open', // open → in_progress → in_review → closed | failed
    retries: 0,
    assignee: null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    closedAt: null,
    error: null,
  };
  appendJsonl(BEADS_FILE, bead);
  return bead;
}

export function createConvoy({ title, description = '', beadIds = [] }) {
  const id = `convoy-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
  const convoy = {
    id,
    title,
    description,
    beadIds,
    status: 'staged', // staged → active → closed
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  appendJsonl(CONVOYS_FILE, convoy);
  return convoy;
}

// ---------------------------------------------------------------------------
// Reconciler — the engine that drives the town
//   Each tick (5s): drain → evaluate → dispatch → enforce
// ---------------------------------------------------------------------------

function dispatchReadyBeads(beads, convoys) {
  const dispatched = [];
  for (const bead of beads) {
    if (bead.status !== 'open') continue;
    // Invariant: dependencies must be satisfied (all parents closed/removed).
    const parentsSatisfied = (bead.parents || []).every((pid) => {
      const p = beads.find((b) => b.id === pid);
      return !p || p.status === 'closed';
    });
    if (!parentsSatisfied) continue;
    // Enforce capacity: no double-dispatch of the same bead.
    if (beads.some((b) => b.id !== bead.id && b.assignee === bead.role && b.status === 'in_progress')) {
      continue; // one in-flight bead per role lane (bounded concurrency)
    }
    bead.status = 'in_progress';
    bead.assignee = bead.role; // role stands in for the polecat id
    bead.updatedAt = new Date().toISOString();
    appendJsonl(BEADS_FILE, bead);
    dispatched.push(bead.id);
  }
  // Activate any convoy whose beads are now running.
  if (convoys && dispatched.length) {
    for (const convoy of convoys) {
      if (convoy.status === 'staged' && (convoy.beadIds || []).some((id) => beads.find((b) => b.id === id)?.status === 'in_progress')) {
        convoy.status = 'active';
        convoy.updatedAt = new Date().toISOString();
        appendJsonl(CONVOYS_FILE, convoy);
      }
    }
  }
  return dispatched;
}

function finalizeBeads(beads) {
  const closedIds = new Set();
  for (const bead of beads) {
    if (bead.status === 'in_review') {
      // Refinery adversarial gate: a bead in review is only closed when a
      // review marker is set. In this engine, review is modeled by the
      // transition in_review → closed via completeReview(); auto-close here
      // is intentionally NOT done (review is the gate).
      continue;
    }
  }
  return closedIds.size;
}

export function tick(beads, convoys) {
  const dispatched = dispatchReadyBeads(beads, convoys);
  finalizeBeads(beads);
  return { dispatched, tickedAt: new Date().toISOString() };
}

// ---------------------------------------------------------------------------
// Witness — health monitor (detect stuck polecats)
// ---------------------------------------------------------------------------

export function witnessInspect(beads) {
  const stuck = [];
  const now = Date.now();
  for (const bead of beads) {
    if (bead.status === 'in_progress' && bead.updatedAt) {
      const ageMs = now - new Date(bead.updatedAt).getTime();
      if (ageMs > STUCK_MS && bead.retries < MAX_RETRIES) {
        stuck.push({ id: bead.id, assignee: bead.assignee, ageMs });
        bead.retries += 1;
        bead.status = 'open'; // recycle back to open (Witness nudges + recycles)
        bead.updatedAt = new Date().toISOString();
        appendJsonl(BEADS_FILE, bead);
      } else if (ageMs > STUCK_MS) {
        // Exhausted retries: fail the bead (bounded).
        bead.status = 'failed';
        bead.error = 'stuck: retries exhausted';
        bead.updatedAt = new Date().toISOString();
        appendJsonl(BEADS_FILE, bead);
      }
    }
  }
  return stuck;
}

// ---------------------------------------------------------------------------
// Actions used by the Mayor / agents
// ---------------------------------------------------------------------------

export function startBead(beadId, beads) {
  const b = beads.find((x) => x.id === beadId);
  if (!b || b.status !== 'open') return null;
  b.status = 'in_progress';
  b.assignee = b.role;
  b.updatedAt = new Date().toISOString();
  appendJsonl(BEADS_FILE, b);
  return b;
}

export function completeBead(beadId, result, beads) {
  const b = beads.find((x) => x.id === beadId);
  if (!b || b.status !== 'in_progress') return null;
  // Send to Refinery for adversarial review before close.
  b.status = 'in_review';
  b.result = result;
  b.updatedAt = new Date().toISOString();
  appendJsonl(BEADS_FILE, b);
  return b;
}

export function completeReview(beadId, approved, note, beads) {
  const b = beads.find((x) => x.id === beadId);
  if (!b || b.status !== 'in_review') return null;
  if (approved) {
    b.status = 'closed';
    b.closedAt = new Date().toISOString();
    b.reviewNote = note || 'approved';
  } else {
    b.status = 'in_progress'; // send back for revision (micro-adversarial loop)
    b.reviewNote = note || 'needs revision';
    b.updatedAt = new Date().toISOString();
  }
  appendJsonl(BEADS_FILE, b);
  return b;
}

export function heartbeatsSnapshot() {
  return readJsonl(HEARTBEATS_FILE);
}

// In-flight town state (loaded fresh on each call so the dashboard reflects
// persisted reality — mirrors Kilo reading from beads store).
export function getTownState() {
  const { beads, convoys, heartbeats } = loadTown();
  return {
    beads: beads.length,
    convoys: convoys.length,
    byStatus: beads.reduce((acc, b) => {
      acc[b.status] = (acc[b.status] || 0) + 1;
      return acc;
    }, {}),
    openReady: beads.filter((b) => b.status === 'open' && (b.parents || []).every((p) => !beads.find((x) => x.id === p) || beads.find((x) => x.id === p).status === 'closed')).length,
    inReview: beads.filter((b) => b.status === 'in_review').length,
    stuck: witnessInspect(beads).length,
    roles: TOWN_ROLES,
    reconcilerTickMs: RECONCILER_TICK_MS,
    heartbeats: heartbeats.slice(-20),
  };
}

export default { createBead, createConvoy, tick, witnessInspect, startBead, completeBead, completeReview, getTownState, TOWN_ROLES };

/**
 * services/agents/hermes.js
 * ---------------------------------------------------------------------------
 * HERMES — the "Autonomous Logic Auditor".
 *
 * HERMES continuously inspects the Redis memory layer for:
 *   1. Inefficiencies in the persistent memory (redundant / overlapping
 *      session logs, duplicate governance actions, bloated feeds).
 *   2. Unoptimized prompt/logic pairs that could be tagged and promoted into
 *      the "Proven" index so the Governance router can serve them on the
 *      Fast-Brain path instead of paying for Slow-Brain LLM reasoning.
 *
 * All HERMES background output is funneled through a custom log formatter so
 * that every action appears in the Control Tower terminal with a
 * `[HERMES:AUDITOR]` prefix.
 *
 * HERMES exposes:
 *   - hermes.runAudit()           -> one audit pass (used by the worker loop)
 *   - hermes.console.console.log(...)             -> prefixed logger
 *   - hermes.publishHeartbeat()   -> reports status to the Control Tower
 * ---------------------------------------------------------------------------
 */

import { getSlowRedisClient, isUpstashMaxRequestsError } from '../lib/redis.js';
import { hermesHeartbeatBreaker } from '../lib/circuitBreaker.ts';
import { matchLogic, proposeAction, listProposed } from '../governance/router.js';
import { runInsert } from '../lib/db.js';

const AGENT_ID = `hermes-auditor-${process.pid}`;
const PREFIX = '[HERMES:AUDITOR]';
const HEARTBEAT_KEY = 'kudbee:agents:hermes';

// ── Local filesystem fallback (72h Redis quota survival) ──────────────────
import { join } from 'node:path';
import { mkdirSync, existsSync, writeFileSync } from 'node:fs';
const LOCAL_STATE_DIR = join(process.cwd(), '.kilo', 'memory', 'local-state');
function localHeartbeatWrite(payload) {
  try {
    if (!existsSync(LOCAL_STATE_DIR)) mkdirSync(LOCAL_STATE_DIR, { recursive: true });
    writeFileSync(join(LOCAL_STATE_DIR, 'hermes-heartbeat.json'), JSON.stringify(payload));
    console.console.console.log(`${PREFIX} heartbeat → local filesystem (Redis unavailable)`);
  } catch (e) { /* silent */ }
}
const HEARTBEAT_TTL = 360; // seconds — window Control Tower treats as "Online".
// Matches the 5-minute worker heartbeat interval (quota protection);
// a 30s TTL would show the auditor as Offline between heartbeats.
const LOG_STREAM_KEY = 'kudbee:hermes:log'; // surfaced in the dashboard terminal
const LOG_STREAM_MAX = 200;
const THINK_STREAM_KEY = 'kudbee:think:stream'; // live thought-stream for the dashboard
const THINK_STREAM_MAX = 200;

// --- Custom log formatter -------------------------------------------------
// Every HERMES background action is rendered with the [HERMES:AUDITOR] prefix
// (plus an optional sub-tag) so it is visually distinct in the dashboard dock.
// Each formatted line is also mirrored to the Redis log stream so the
// Control Tower terminal can display HERMES output in real time.
function format(level, parts) {
  const ts = new Date().toISOString();
  const head = `${PREFIX} ${level}`;
  const body = parts
    .map((p) => (typeof p === 'string' ? p : JSON.stringify(p)))
    .join(' ');
  return `${ts} ${head} ${body}`;
}

async function mirrorToStream(line) {
  try {
    const redis = getSlowRedisClient({ label: 'hermes' });
    const ts = new Date().toISOString();
    await redis.lpush(LOG_STREAM_KEY, JSON.stringify({ ts, line }));
    await redis.ltrim(LOG_STREAM_KEY, 0, LOG_STREAM_MAX);
    // Native SSE broadcast: re-publish each [HERMES:AUDITOR] line onto the
    // cross-process event bus so the ingestion server's SSE subscriber fans it
    // out to dashboard clients in real time (drives the HERMES Auditor plugin
    // via EventSource instead of a 5s polling loop). Best-effort: a publish
    // failure must never block the audit loop.
    await redis.publish(
      'kudbee:events',
      JSON.stringify({
        type: 'hermes',
        data: { ts, line, agent: 'HERMES' },
        ts
      })
    );
  } catch {
    /* best-effort; never block the audit loop on log mirroring */
  }
}

export const log = Object.freeze({
  info: (...parts) => { const l = format('INFO', parts); console.console.console.log(l); void mirrorToStream(l); },
  warn: (...parts) => { const l = format('WARN', parts); console.warn(l); void mirrorToStream(l); },
  audit: (...parts) => { const l = format('AUDIT', parts); console.console.console.log(l); void mirrorToStream(l); },
  error: (...parts) => { const l = format('ERROR', parts); console.error(l); void mirrorToStream(l); }
});

/**
 * Reports a heartbeat to the Control Tower so the global status bar can show
 * HERMES as "Online" / "Offline". We publish both:
 *   - a Redis key with a short TTL (the authoritative source for the status bar),
 *   - a POST to /api/health (best-effort) when APP_URL is configured.
 *
 * The Control Tower reads `kudbee:agents:hermes` and treats a missing/expired
 * key as Offline. The worker also pushes this on a fixed interval.
 */
export async function publishHeartbeat() {
  const payload = {
    agent: 'HERMES', status: 'Online', pid: process.pid, timestamp: new Date().toISOString()
  };
  await hermesHeartbeatBreaker.execute(
    async () => {
      const redis = getSlowRedisClient({ label: 'hermes' });
      await redis.set(HEARTBEAT_KEY, JSON.stringify(payload), 'EX', HEARTBEAT_TTL);
    },
    async () => localHeartbeatWrite(payload)
  );

  const appUrl = process.env.APP_URL || '';
  if (appUrl) {
    try {
      await fetch(`${appUrl.replace(/\/$/, '')}/api/health`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ agent: 'HERMES', status: 'Online' })
      });
    } catch {
      /* best-effort; ignore network errors */
    }
  }
}

export async function reportOffline() {
  const redis = getSlowRedisClient({ label: 'hermes' });
  try {
    await redis.set(
      HEARTBEAT_KEY,
      JSON.stringify({ agent: 'HERMES', status: 'Offline', timestamp: new Date().toISOString() }),
      'EX',
      HEARTBEAT_TTL
    );
  } catch {
    /* ignore */
  }
}

// --- Audit routines -------------------------------------------------------

/**
 * Detect redundant / overlapping session logs in the persistent memory layer.
 * Two session-history entries are "overlapping" when they carry the same
 * agent/trace signature or an identical summary hash, which wastes memory and
 * pollutes recall.
 */
async function auditMemoryLayer(redis) {
  const findings = [];
  try {
    // Respect circuit breaker — skip when Redis quota exhausted
    const { getRedisQuotaBackoffRemaining } = await import('../lib/redis.js');
    if (getRedisQuotaBackoffRemaining() > 0) {
      log.warn('auditMemoryLayer skipped — Redis quota backoff active');
      return findings;
    }
    const raw = await redis.lrange('kudbee:session_history', 0, -1);
    const seen = new Map();
    let duplicates = 0;
    const parsed = raw.map((r) => {
      try { return JSON.parse(r); } catch { return null; }
    }).filter(Boolean);

    for (const entry of parsed) {
      const key = entry.trace_id || entry.sessionId || entry.summary || entry.raw || '';
      if (!key) continue;
      if (seen.has(key)) {
        duplicates += 1;
      } else {
        seen.set(key, 1);
      }
    }
    if (duplicates > 0) {
      findings.push({
        type: 'redundant_session_logs',
        count: duplicates,
        detail: `Detected ${duplicates} overlapping/duplicate session log signature(s).`
      });
    }

    // Flag oversized telemetry feed (LTRIM keeps 10k, but warn above 8k).
    const feedLen = await redis.llen('kudbee:telemetry_feed');
    if (feedLen > 8000) {
      findings.push({
        type: 'oversized_telemetry_feed',
        count: feedLen,
        detail: `Telemetry feed length ${feedLen} approaching cap — consider archival.`
      });
    }
  } catch (err) {
    log.error('memory layer audit failed:', err.message);
  }
  return findings;
}

/**
 * Scan the proposed-action queue for unoptimized prompt/logic pairs that are
 * strong candidates to be tagged and promoted into the "Proven" index so the
 * Governance router can serve them via Fast-Brain matching.
 */
async function auditUnoptimizedLogic() {
  const findings = [];
  try {
    const proposed = await listProposed();
    for (const entry of proposed) {
      const prompt = entry.prompt || '';
      const match = await matchLogic(prompt);
      // A proposed action whose prompt already has a near-match, or that is
      // well-formed and self-contained, is a good candidate for the Proven index.
      if (match.matched || (prompt.length > 24 && entry.action)) {
        findings.push({
          type: 'promotable_logic_pair',
          id: entry.id,
          tags: entry.tags,
          detail: `Prompt/logic pair "${prompt.slice(0, 60)}…" is a candidate for the Proven index.`
        });
      }
    }
  } catch (err) {
    log.error('logic audit failed:', err.message);
  }
  return findings;
}

/**
 * Performs a single full audit pass. Surfaces findings as `AUDIT` log lines
 * and persists promotable logic pairs as new "Proposed" governance actions so
 * a human can approve them into the Proven index via the dashboard.
 */
export async function runAudit() {
  const redis = getSlowRedisClient({ label: 'hermes' });
  log.audit('audit pass started');

  const memoryFindings = await auditMemoryLayer(redis);
  const logicFindings = await auditUnoptimizedLogic();

  for (const f of memoryFindings) {
    log.warn(`memory:${f.type}`, `(${f.count})`, f.detail);
    await publishAuditEvent('hermes_suggestion', {
      id: `mem-${f.type}-${Date.now()}`,
      action: 'OPTIMIZE_MEMORY',
      tags: ['hermes-auditor', 'memory'],
      prompt: f.detail,
      detail: f.detail
    });
  }

  let promoted = 0;
  for (const f of logicFindings) {
    if (f.type === 'promotable_logic_pair') {
      log.audit('promotable', `id=${f.id}`, `tags=${JSON.stringify(f.tags)}`, f.detail);
      try {
        const proposed = await proposeAction({
          action: `PROMOTE_LOGIC:${f.id}`,
          tags: Array.isArray(f.tags) ? f.tags.concat('hermes-audited') : ['hermes-audited'],
          prompt: `Audit promotion candidate ${f.id}`,
          id: `hermes-${f.id}`
        });
        promoted += 1;
        await publishAuditEvent('hermes_suggestion', {
          id: proposed.id,
          action: proposed.action,
          tags: proposed.tags,
          prompt: proposed.prompt,
          detail: f.detail
        });
      } catch (err) {
        log.error('failed to propose promotion:', err.message);
      }
    }
  }

  const hasRiskyMemoryFindings = memoryFindings.length > 0;
  const tokenStatus = hasRiskyMemoryFindings ? 'PENDING_APPROVAL' : 'VERIFIED';

  try {
    const { mintThinkToken } = await import('../memory/thinkTokenGenerator.ts');
    await mintThinkToken({
      agentId: AGENT_ID,
      taskContext: {
        audit_type: 'hermes_runAudit',
        memory_findings: memoryFindings.length,
        logic_findings: logicFindings.length,
        promoted
      },
      failedState: hasRiskyMemoryFindings ? { risk: 'memory_inefficiency', findings: memoryFindings } : {},
      correctionDelta: `Audited ${memoryFindings.length} memory + ${logicFindings.length} logic findings; promoted ${promoted}.`,
      reasoningSteps: [
        `memory_findings=${memoryFindings.length}`,
        `logic_findings=${logicFindings.length}`,
        `promoted=${promoted}`
      ],
      status: tokenStatus
    });
  } catch (err) {
    log.warn('think token minting failed (degraded):', err.message);
  }

  log.audit(
    `audit pass complete — memory_findings=${memoryFindings.length}, ` +
      `logic_findings=${logicFindings.length}, promoted=${promoted}`
  );

  return { memoryFindings, logicFindings, promoted };
}

// Publish an audit finding to the real-time event bus (best-effort).
async function publishAuditEvent(type, data) {
  try {
    const redis = getSlowRedisClient({ label: 'hermes' });
    await redis.publish('kudbee:events', JSON.stringify({ type, data, ts: new Date().toISOString() }));
  } catch {
    /* ignore */
  }
}

// --- Thought-Stream Interceptor --------------------------------------------
// The "Think" layer: every task the Release Engineer performs archives its
// chain-of-thought into the `think` database (Neon, with in-memory fallback).
// This makes the agent's reasoning process observable, auditable, and
// recallable — closing the full loop from code -> verification -> archival.
//
// Resilient-First: a failure to persist a thought is logged as a warning and
// NEVER crashes the process. A thought is diagnostic metadata, not a hard
// invariant, so it must degrade gracefully.
export async function archive_thought(thought_block) {
  const block = {
    agent_id: thought_block?.agent_id ?? AGENT_ID,
    task: thought_block?.task ?? null,
    phase: thought_block?.phase ?? null,
    thought: thought_block?.thought ?? '',
    tokens_in: Number(thought_block?.tokens_in) || 0,
    tokens_out: Number(thought_block?.tokens_out) || 0,
    model: thought_block?.model ?? 'reasoning',
    created_at: new Date().toISOString()
  };

  // Best-effort live mirror to the dashboard thought-stream (Resilient-First).
  try {
    const redis = getSlowRedisClient({ label: 'hermes' });
    await redis.lpush(
      THINK_STREAM_KEY,
      JSON.stringify({ ts: block.created_at, agent: block.agent_id, thought: block.thought, task: block.task })
    );
    await redis.ltrim(THINK_STREAM_KEY, 0, THINK_STREAM_MAX);
  } catch {
    /* never block on log mirroring */
  }

  try {
    await runInsert(
      `INSERT INTO think (agent_id, task, phase, thought, tokens_in, tokens_out, model, created_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())`,
      [block.agent_id, block.task, block.phase, block.thought, block.tokens_in, block.tokens_out, block.model]
    );
    log.audit('think archived', block.task ? `task=${block.task}` : '', `len=${block.thought.length}`);
    return { ok: true, task: block.task };
  } catch (err) {
    log.warn('think archive failed (degraded):', err.message);
    return { ok: false, error: err.message };
  }
}

/**
 * HERMES core system prompt — mandates blueprint-first reasoning.
 *
 * Whenever HERMES is asked to write routes, modify schemas, or touch
 * infrastructure, it MUST first query the Self-Aware Vector Memory Layer
 * (query_system_topology) to inspect the actual system topology before
 * emitting code. This keeps agent-authored changes consistent with the
 * verified architecture instead of guessing.
 */
export const HERMES_SYSTEM_PROMPT = `You are HERMES, the Autonomous Logic Auditor for the Kudbee control tower.

BLUEPRINT-FIRST MANDATE: Before you write any route, modify any schema, or
change infrastructure, you MUST call query_system_topology to inspect the
system blueprint (architecture docs, layout components, router rules, and
type contracts) stored in the vector memory layer. Reason from that verified
topology — never guess at the structure.

OPERATING PRINCIPLES:
- Resilient-First: degrade gracefully, log warnings, never crash.
- Prefer the Proven (Fast Brain) logic path; fall back to reasoning only when
  no match exists.
- Archive your chain-of-thought via archive_thought for every task.`;

/**
 * Native core tool for HERMES: semantic lookup against the system blueprint.
 *
 * Embeds the query text locally and retrieves the most relevant topology
 * chunks (Resilient-First — degrades to the in-memory mock when the database
 * is unavailable). Returns the matched chunks or an empty list.
 */
export async function query_system_topology(query, limit = 5) {
  try {
    const { embedTextLocal } = await import('../memory/embedText.ts');
    const { querySystemTopology } = await import('../memory/vectorStore.ts');
    const embedding = embedTextLocal(query);
    const result = await querySystemTopology(embedding, limit);
    if (!result.ok) {
      log.warn('system topology query degraded:', result.error);
      return [];
    }
    log.audit('system topology queried', `q="${query.slice(0, 40)}…"`, `hits=${result.results.length}`);
    return result.results;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    log.warn('system topology query failed (degraded):', message);
    return [];
  }
}

export const hermes = {
  agentId: AGENT_ID,
  prefix: PREFIX,
  log,
  runAudit,
  publishHeartbeat,
  reportOffline,
  archive_thought,
  query_system_topology,
  systemPrompt: HERMES_SYSTEM_PROMPT
};


export default hermes;

import express from 'express';
import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
