        : 'Telemetry trace ingested successfully',
    };

    // Real egressed signal — built unconditionally so the SSE broadcast
    // below always has valid data, then mirrored to the Redis feed (best-effort
    // when a cache is configured).
    const feedEntry = {
      trace_id: trace_id ?? (agentId ? `agent-${agentId}` : 'unknown'),
      model: model || 'unknown',
      tokens_in: Number(tokens_in) || 0,
      tokens_out: Number(tokens_out) || 0,
      cost: Number(cost) || 0,
      status: effectiveStatus,
      provider: provider || 'unknown',
      project_name: project_name || 'kilo-fuel-gauge',
      timestamp: new Date().toISOString(),
    };

    if (redis) {
      redis
        .lpush('kudbee:telemetry_feed', JSON.stringify(feedEntry))
        .then(() => redis.ltrim('kudbee:telemetry_feed', 0, 9999))
        .catch(async (e) => {
          console.error('[Redis] Telemetry feed push failed:', e.message);
          const { getOrCreateInMemoryQueue } = await import('../lib/inMemoryQueue.ts');
          const fallbackQueue = getOrCreateInMemoryQueue();
          fallbackQueue.enqueue({
            queue: 'kudbee:telemetry_feed',
            data: feedEntry,
            source: 'ingestion-telemetry-feed',
          });
        });
    } else {
      const { getOrCreateInMemoryQueue } = await import('../lib/inMemoryQueue.ts');
      const fallbackQueue = getOrCreateInMemoryQueue();
      fallbackQueue.enqueue({
        queue: 'kudbee:telemetry_feed',
        data: feedEntry,
        source: 'ingestion-telemetry-feed',
      });
    }

    // Native SSE broadcast of the real egressed signal so the Edge Sentinel
    // plugin can pulse/shift on live ingress events (replaces polling).
    publishEvent('telemetry', {
      trace_id: feedEntry.trace_id,
      model: feedEntry.model,
      tokens_in: feedEntry.tokens_in,
      tokens_out: feedEntry.tokens_out,
      cost: feedEntry.cost,
      status: feedEntry.status,
      latency_ms: 0,
      agent: agentId || null,
      ts: feedEntry.timestamp,
    });

    publishEvent('memory.ingested', {
      trace_id: feedEntry.trace_id,
      agentId: agentId || null,
      category: effectiveStatus === 'OK' ? 'FACT' : 'OBSERVATION',
      importance: isHighValueModel ? 0.9 : 0.5,
      content: (effectiveThought || effectiveReasoning || feedEntry.trace_id).slice(0, 80),
      ts: feedEntry.timestamp,
    });

    return res.status(201).json(responsePayload);
  } catch (err) {
    console.error('[Ingest] Error:', err.message);
    return res.status(500).json({ error: 'Internal server error', details: err.message });
  }
});

// --- Batch telemetry ingest: accepts an array of events in a single request ---
app.post('/api/telemetry/ingest/batch', async (req, res) => {
  try {
    const events = req.body?.events;
    if (!Array.isArray(events) || events.length === 0) {
      return res.status(400).json({ error: 'events array is required' });
    }
    if (events.length > 100) {
      return res.status(400).json({ error: 'batch limited to 100 events' });
    }

    const dbHealthy = isDbHealthy();
    if (!dbHealthy && !redis) {
      return res
        .status(503)
        .json({ error: 'Service Unavailable', reason: 'DB and cache unreachable' });
    }

    const agentId = authenticateAgentPass(req.header('X-Agent-Pass'));
    let persisted = 0;
    let filtered = 0;
    let sampled = 0;
    let deduped = 0;

    for (const event of events) {
      const { trace_id, model, tokens_in, tokens_out, cost, status, provider, project_name } =
        event || {};
      recordThroughput();

      if (
        isLowValueEvent({ trace_id, model, tokens_in, tokens_out, cost, status: status || 'OK' })
      ) {
        filtered++;
        continue;
      }
    if (!agentId && await isDuplicateTrace(trace_id)) {
        deduped++;
        continue;
      }
      if (!agentId && !shouldSample()) {
        sampled++;
        continue;
      }

      const effectiveStatus = agentId ? status || 'authenticated_bypass' : status || 'OK';
      const isHeartbeatPing =
        Number(tokens_in) <= 1 && Number(tokens_out) <= 1 && effectiveStatus === 'OK';
      const isHighValue = HIGH_VALUE_MODELS.has(String(model || '').toLowerCase());
      if (!isHeartbeatPing || isHighValue) {
        await runInsert(
          `INSERT INTO telemetry_traces (trace_id, model, tokens_in, tokens_out, cost, status, provider, project_name, timestamp, input_tokens, output_tokens)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW(), $3, $4)
           ON CONFLICT (trace_id) DO UPDATE SET tokens_in = EXCLUDED.tokens_in, tokens_out = EXCLUDED.tokens_out, cost = EXCLUDED.cost, status = EXCLUDED.status, timestamp = NOW()`,
          [
            String(trace_id),
            String(model || 'unknown'),
            Number(tokens_in) || 0,
            Number(tokens_out) || 0,
            Number(cost) || 0,
            String(effectiveStatus),
            String(provider || 'unknown'),
            String(project_name || 'kilo-fuel-gauge'),
          ]
        ).catch(() => {
          filtered++;
        });
        persisted++;
      } else {
        filtered++;
      }
    }

    return res.status(201).json({
      success: true,
      received: events.length,
      persisted,
      filtered,
      sampled,
      deduped,
      message: `Batch processed: ${persisted} persisted, ${filtered} filtered, ${sampled} sampled, ${deduped} deduped`,
    });
  } catch (err) {
    console.error('[Ingest:Batch] Error:', err.message);
    return res.status(500).json({ error: 'Batch ingest failed', details: err.message });
  }
});

// --- Agent Verification / Handshake Endpoint --------------------------------
// Allows existing workers to securely prove their identity before making
// authenticated requests. The agent signs a challenge with its private key;
// the server verifies it against the registered public key in config/agents.json.
app.post('/api/agents/verify', express.json(), (req, res) => {
  try {
    const { agentId, publicKey, challenge, signature } = req.body || {};

    if (!agentId || !publicKey || !challenge || !signature) {
      return res.status(400).json({
        verified: false,
        error: 'Missing required fields: agentId, publicKey, challenge, signature',
      });
    }

    const registryKey = AGENT_REGISTRY.get(agentId);
    if (!registryKey) {
      return res.status(401).json({
        verified: false,
        error: `Agent '${agentId}' is not registered`,
      });
    }

    if (registryKey !== publicKey) {
      return res.status(401).json({
        verified: false,
        error: 'Public key does not match registered key for this agent',
      });
    }

    const isValid = verifySignature(publicKey, challenge, signature);
    if (!isValid) {
      return res.status(401).json({
        verified: false,
        error: 'Invalid signature for challenge',
      });
    }

    return res.status(200).json({
      verified: true,
      agentId,
      serverTime: new Date().toISOString(),
    });
  } catch (err) {
    console.error('[AgentVerify] Error:', err.message);
    return res.status(500).json({ verified: false, error: 'Verification failed' });
  }
});

