// --- Real-time telemetry: Server-Sent Events (SSE) -----------------------
// The web server and the HERMES worker are separate processes, so we use a
// Redis pub/sub channel (`kudbee:events`) as the cross-process event bus.
// The server subscribes once and fans every event out to all connected SSE
// clients. `broadcast()` writes to local clients; `publishEvent()` also pushes
// to Redis so the worker (and other server dynos) can emit events too.

const EVENTS_CHANNEL = 'kudbee:events';
const MAX_SSE_CLIENTS = 100;
const sseClients = new Set();

function sseClientCount() {
  return sseClients.size;
}

function broadcast(event) {
  const payload = `event: ${event.type}\ndata: ${JSON.stringify(event.data)}\n\n`;
  const deadClients = [];
  for (const res of sseClients) {
    try {
      res.write(payload);
    } catch {
      deadClients.add(res);
    }
  }
  for (const res of deadClients) {
    sseClients.delete(res);
  }
}

function _setupSSEHealth(res, keepAlive) {
  const cleanup = () => {
    clearInterval(keepAlive);
    sseClients.delete(res);
  };
  res.on('close', cleanup);
  res.on('error', (err) => {
    if (err && (err.code === 'ECONNRESET' || err.code === 'EPIPE' || err.code === 'ECONNABORTED')) {
      cleanup();
    }
  });
}

function publishEvent(type, data) {
  // Single delivery path: publish to Redis; the subscriber connection fans
  // out to all local SSE clients. (Calling broadcast() here too would double
  // deliver server-originated events.)
  if (redis) {
    try {
      redis
        .publish(EVENTS_CHANNEL, JSON.stringify({ type, data, ts: new Date().toISOString() }))
        .catch((e) => {
          console.warn('[publishEvent] Redis publish failed:', e.message);
        });
      void publishUnifiedEvent('governance', type, data, EVENTS_CHANNEL);
    } catch {
      /* ignore */
    }
  }
}

// Dedicated subscriber connection (ioredis requires subscriber mode).
// Uses getSubscriberClient() which includes retries, offline queueing, and
// TLS settings so the SSE event bus survives transient Redis outages.
if (redis) {
  try {
    const subClient = getSubscriberClient();
    subClient.subscribe(EVENTS_CHANNEL, (err) => {
      if (err) console.error('[SSE] Failed to subscribe to events channel:', err.message);
      else console.console.console.log('[SSE] Subscribed to', EVENTS_CHANNEL);
    });
    subClient.on('message', (_channel, message) => {
      try {
        const event = JSON.parse(message);
        broadcast(sanitizeEvent(event));
      } catch {
        /* ignore malformed */
      }
    });
    subClient.on('error', (err) => console.error('[SSE] Subscriber error:', err.message));
  } catch (err) {
    console.error('[SSE] Subscriber init error:', err.message);
  }
}

// --- SSE Stream Ticket (zero-trust handshake) ---
const STREAM_TICKETS = new Map();
const TICKET_TTL_MS = 30000;
const STREAM_SECRET = process.env.STREAM_SECRET || crypto.randomBytes(32).toString('hex');

if (!process.env.STREAM_SECRET) {
  console.warn(
    '[SSE] STREAM_SECRET not set — using ephemeral in-memory fallback (signatures reset on restart)'
  );
}

app.post('/api/auth/stream-ticket', (req, res) => {
  const ticket = 'sse_ticket_' + crypto.randomUUID();
  STREAM_TICKETS.set(ticket, Date.now() + TICKET_TTL_MS);
  const sig = crypto
    .createHmac('sha256', STREAM_SECRET)
    .update(ticket + ':' + Date.now())
    .digest('hex');
  res.json({ ticket, signature: sig, expiresIn: TICKET_TTL_MS });
});

// --- Admin session verification (replaces the hardcoded client-side
// passkey in apps/web LoginView). Validates against ADMIN_PASS env var
// (falls back to EDGE_AGENT_PASS for existing single-user setups) and
// returns a short-lived HMAC-signed session token. The passkey is NEVER
// shipped in frontend code.
const ADMIN_SESSION_TTL_MS = 12 * 60 * 60 * 1000; // 12h

function adminPass() {
  return process.env.ADMIN_PASS || process.env.EDGE_AGENT_PASS || '';
}

function signAdminSession() {
  const issued = Date.now();
  const token = `admin_${crypto.randomUUID()}`;
  const sig = crypto
    .createHmac('sha256', SESSION_SECRET)
    .update(`${token}:${issued}`)
    .digest('hex');
  return { token, sig, issued, expiresAt: issued + ADMIN_SESSION_TTL_MS };
}

app.post('/api/admin/verify-pass', (req, res) => {
  const expected = adminPass();
  if (!expected) {
    // No admin pass configured — deny rather than fall back to an open door.
    return res.status(503).json({ error: 'ADMIN_PASS not configured on server' });
  }
  const provided = String((req.body && req.body.passkey) || '');
  if (!provided || provided.length > 512) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Constant-time comparison to avoid timing side-channels.
  const a = Buffer.from(provided);
  const b = Buffer.from(expected);
  const ok = a.length === b.length && crypto.timingSafeEqual(a, b);
  if (!ok) return res.status(401).json({ error: 'Unauthorized' });
  const session = signAdminSession();
  res.json({ authenticated: true, session });
});

function validateStreamTicket(ticket) {
  if (!ticket) return false;
  const exp = STREAM_TICKETS.get(ticket);
  if (!exp || Date.now() > exp) {
    STREAM_TICKETS.delete(ticket);
    return false;
  }
  STREAM_TICKETS.delete(ticket);
  return true;
}

setInterval(() => {
  const now = Date.now();
  for (const [t, e] of STREAM_TICKETS) if (now > e) STREAM_TICKETS.delete(t);
}, 60000);

app.get('/api/events', async (req, res) => {
  if (sseClientCount() >= MAX_SSE_CLIENTS) {
    res.writeHead(503, { 'Content-Type': 'application/json', 'Retry-After': '5' });
    return res.end(
      JSON.stringify({
        error: 'Service Unavailable',
        reason: 'SSE client limit reached (backpressure)',
      })
    );
  }

  const ticket = req.query?.ticket || req.url?.split('ticket=')[1]?.split('&')[0];
  if (!validateStreamTicket(ticket)) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({
      error: 'Unauthorized',
      reason: 'missing or invalid stream ticket. Obtain one via POST /api/auth/stream-ticket',
    }));
  }

  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.write('retry: 3000\n\n');
  if (typeof res.flushHeaders === 'function') res.flushHeaders();
  sseClients.add(res);

  try {
    const proposed = redis ? await listProposed() : [];
    res.write(
      `event: snapshot\ndata: ${JSON.stringify({ proposed: Array.isArray(proposed) ? proposed : [], db_healthy: isDbHealthy(), redis: !!redis })}\n\n`
    );
  } catch {
    /* ignore */
  }

  const keepAlive = setInterval(() => {
    try {
      res.write(`: ping\n\n`);
    } catch {
      /* ignore */
    }
  }, 10_000);

  _setupSSEHealth(res, keepAlive);
});

// --- Unified OS Stream: single SSE connection replacing per-panel polling ---
const OS_STREAM_CLIENTS = new Set();
const OS_STREAM_INTERVAL_MS = 5_000;

async function buildOsSnapshot() {
  const dbHealthy = isDbHealthy();
  const redisOk = !!redis;
  const bootTime = _state.bootTimeRef.value;
  const uptimeSec = bootTime ? Math.floor((Date.now() - bootTime) / 1000) : 0;

  let pgLatency = null;
  try {
    const t0 = Date.now();
    await runQuery('SELECT 1 as ok');
    pgLatency = dbHealthy ? Date.now() - t0 : null;
  } catch {
    /* ignore */
  }

  let redisLatency = null;
  if (redisOk) {
    try {
      const t0 = Date.now();
      await redis.ping();
      redisLatency = Date.now() - t0;
    } catch {
      /* ignore */
    }
  }

  let pendingActions = [];
  let thinkStats = { tokens: 0, verified: 0 };
  let memoryStats = { vectors: 0, chunks: 0 };
  let alertCount = 0;

  try {
    pendingActions = redisOk ? await listProposed() : [];
  } catch {}
  try {
    thinkStats = {
      tokens:
        (
          await runQuery('SELECT COUNT(*) as count FROM think_tokens').catch(() => [{ count: 0 }])
        )[0]?.count ?? 0,
      verified:
        (
          await runQuery(
            "SELECT COUNT(*) as count FROM think_tokens WHERE status = 'VERIFIED'"
          ).catch(() => [{ count: 0 }])
        )[0]?.count ?? 0,
    };
  } catch {}
  try {
    memoryStats = {
      vectors:
        (
          await runQuery('SELECT COUNT(*) as count FROM vector_memory').catch(() => [{ count: 0 }])
        )[0]?.count ?? 0,
      chunks:
        (
          await runQuery('SELECT COUNT(*) as count FROM system_topology_embeddings').catch(() => [
            { count: 0 },
          ])
        )[0]?.count ?? 0,
    };
  } catch {}
  try {
    const alerts = _state.alertsState?.alerts;
    alertCount = Array.isArray(alerts) ? alerts.length : 0;
  } catch {}

  return {
    ts: new Date().toISOString(),
    uptime: uptimeSec,
    services: {
      postgres: { ok: dbHealthy, latencyMs: pgLatency },
      redis: { ok: redisOk, latencyMs: redisLatency },
    },
    governance: { pending: pendingActions.length },
    think: thinkStats,
    memory: memoryStats,
    alerts: alertCount,
  };
}

app.get('/api/os-stream', async (req, res) => {
  if (OS_STREAM_CLIENTS.size >= MAX_SSE_CLIENTS) {
    res.writeHead(503, { 'Content-Type': 'application/json', 'Retry-After': '5' });
    return res.end(
      JSON.stringify({ error: 'Service Unavailable', reason: 'SSE client limit reached' })
    );
  }

  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.write('retry: 5000\n\n');
  if (typeof res.flushHeaders === 'function') res.flushHeaders();
  OS_STREAM_CLIENTS.add(res);

  try {
    const snapshot = await buildOsSnapshot();
    res.write(`event: os:snapshot\ndata: ${JSON.stringify(snapshot)}\n\n`);
  } catch {
    /* ignore */
  }

  const interval = setInterval(async () => {
    try {
      const snap = await buildOsSnapshot();
      res.write(`event: os:snapshot\ndata: ${JSON.stringify(snap)}\n\n`);
    } catch {
      /* ignore */
    }
  }, OS_STREAM_INTERVAL_MS);

  const cleanup = () => {
    clearInterval(interval);
    OS_STREAM_CLIENTS.delete(res);
  };
  res.on('close', cleanup);
  res.on('error', (err) => {
    if (err && (err.code === 'ECONNRESET' || err.code === 'EPIPE' || err.code === 'ECONNABORTED')) {
      cleanup();
    }
  });
});

