const PROVIDER_CONFIG = {
  openai: {
    id: 'openai',
    label: 'OpenAI',
    weight: 30,
    baseLatencyMs: 145,
    maxLatencyMs: 800,
    rateLimitPct: 0.0,
    healthy: true,
    lastError: null,
  },
  anthropic: {
