app.post('/api/governance/feedback', async (req, res) => {
  try {
    const { traceId, verdict, policyTag, expectedBehavior, notes } = req.body || {};
    if (!traceId || !verdict) {
      return res.status(400).json({ error: 'traceId and verdict are required' });
