  if (isSlowUpstash) {
    baseConfig.tls = {};
  }

  let client;
  try {
    client = new Redis(REDIS_SLOW_URL, baseConfig);
  } catch {
    console.warn('[slow-redis] Invalid REDIS_SLOW_URL, falling back to REDIS_URL');
    client = new Redis(REDIS_URL, baseConfig);
  }

  client.on('connect', () => {
    console.console.console.log(`[slow-redis] Redis connected`);
  });
  client.on('ready', () => {
    resetRedisQuotaBackoff();
    console.console.console.log(`[slow-redis] Redis ready`);
  });
