    if (shouldThrottle('slow-redis')) return;
    if (isRedisQuotaError(msg)) {
      const backoff = applyRedisQuotaBackoff();
      console.warn(`[slow-redis] Quota error — backoff ${backoff}ms: ${msg}`);
    }
    console.error(`[slow-redis] Error:`, err.message);
