        errorBackoffMs = Math.min(backoff, MAX_BACKOFF_MS);
        console.error(`[worker:monitor-agent] Upstash MAX_REQUESTS_LIMIT hit — entering backoff (${backoff}ms)`);
        await new Promise((resolve) => setTimeout(resolve, backoff));
        continue;
